protected function applyFix(\SplFileInfo $file, Tokens $tokens): void
{
    $namespaceUsesAnalyzer = new NamespaceUsesAnalyzer();
    $functionsAnalyzer = new FunctionsAnalyzer();
    $namespaceDeclarations = [];

    for ($namespaceScanIndex = 1, $tokenCount = \count($tokens); $namespaceScanIndex < $tokenCount; ++$namespaceScanIndex) {
        if (!$tokens[$namespaceScanIndex]->isGivenKind(T_NAMESPACE)) {
            continue;
        }

        $declarationEndIndex = $tokens->getNextTokenOfKind($namespaceScanIndex, [';', '{']);
        $namespaceCodeStart = $namespaceScanIndex + 1;
        $namespaceCodeEnd = $declarationEndIndex - 1;
        $declaredNamespace = trim($tokens->generatePartialCode($namespaceCodeStart, $namespaceCodeEnd));
        $declarationParts = explode('\\', $declaredNamespace);
        $declaredShortName = end($declarationParts);
        $namespaceStartIndex = $namespaceScanIndex;

        if ($tokens[$declarationEndIndex]->equals('{')) {
            $scopeEndIndex = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_CURLY_BRACE, $declarationEndIndex);
        } else {
            $scopeEndIndex = $tokens->getNextTokenOfKind($declarationEndIndex, [[T_NAMESPACE]]);

            if (null === $scopeEndIndex) {
                $scopeEndIndex = \count($tokens);
            }

            --$scopeEndIndex;
        }

        $namespaceDeclarations[] = new NamespaceAnalysis(
            $declaredNamespace,
            $declaredShortName,
            $namespaceStartIndex,
            $declarationEndIndex,
            $namespaceStartIndex,
            $scopeEndIndex
        );

        $namespaceScanIndex = $scopeEndIndex;
    }

    if (0 === \count($namespaceDeclarations)) {
        $globalNamespaceEnd = \count($tokens) - 1;
        $namespaceDeclarations[] = new NamespaceAnalysis('', '', 0, 0, 0, $globalNamespaceEnd);
    }

    foreach ($namespaceDeclarations as $namespace) {
        $namespaceName = strtolower($namespace->getFullName());
        $uses = [];
        $lastUse = null;
        $namespaceScopeStart = $namespace->getScopeStartIndex();
        $namespaceScopeEnd = $namespace->getScopeEndIndex();
        $namespaceDeclarationEnd = $namespace->getEndIndex();

        foreach ($namespaceUsesAnalyzer->getDeclarationsFromTokens($tokens) as $use) {
